def roundrobin(* iterables):
	iter_items = []
	timers = [iter(it) for it in iterables]
	while timers:
		exhausted = []
		for it in timers:
			try:
				data = next(it)
			except StopIteration:
				exhausted.append(it)
				continue
			iter_items.append(data)
			yield data
		for gone in exhausted:
			timers.remove(gone)

