def json_scan(json_obj, key) :
	result = None
	for element in json_obj :
		child = json_obj [element]
		if str(element) == key :
			result = child
		elif isinstance(child, (dict, list)) :
			target = child if isinstance(child, dict) else element
			result = json_scan(target, key)
	return result

